/// Both ends of a ref sit on char boundaries, so the UTF-16 remap is exact; absent optional fields are out of bounds and left untouched.
fn remap_ref(data: &mut [u8], off: usize, remap: &mut dyn FnMut(u32) -> u32) {
    let Some(bytes) = data.get_mut(off..off + 8) else {
        return;
    };
    let start = u32::from_le_bytes(bytes[0..4].try_into().unwrap());
    let len = u32::from_le_bytes(bytes[4..8].try_into().unwrap());
    let new_start = remap(start);
    let new_len = remap(start + len) - new_start;
    bytes[0..4].copy_from_slice(&new_start.to_le_bytes());
    bytes[4..8].copy_from_slice(&new_len.to_le_bytes());
}

